-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 6
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 6 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 06', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 06 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-06.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é um teste end-to-end (E2E) e em que ambiente ele roda.', 0.2, 'O teste end-to-end (E2E) abre o **navegador real**, acessa a **aplicação rodando** e faz o **caminho completo do usuário** (entrar, buscar, adicionar ao carrinho, pagar), confirmando que todas as partes juntas permitem completar a tarefa.', 'Palavras-chave: navegador real; aplicação rodando; caminho completo do usuário. Nota cheia (0,2): definição com o ambiente (navegador real). Metade (0,1): "testa o sistema todo" sem dizer o ambiente. Zero (0): confunde com teste unitário ou com JSDOM.'),
      (v_atividade, 1, 2, 'Compare unitário, integração e E2E quanto ao ambiente, à velocidade e ao tipo de erro que cada um encontra.', 0.4, '**Unitário:** roda no Node, em milissegundos, encontra erro de lógica de uma função. **Integração:** roda no DOM simulado (JSDOM), em décimos de segundo, encontra erro entre componentes. **E2E:** roda no navegador real, em segundos, encontra erro no caminho real do usuário.', 'Palavras-chave: Node / JSDOM / navegador real; milissegundos / décimos de segundo / segundos; lógica / entre componentes / caminho do usuário. Nota cheia (0,4): os três tipos comparados nos três aspectos. Metade (0,2): três tipos com só dois aspectos, ou só dois tipos. Zero (0): comparação errada (ex.: E2E mais rápido).'),
      (v_atividade, 1, 3, 'Explique por que a suíte deve ter poucos testes E2E, só dos fluxos críticos, e muitos unitários.', 0.4, 'O E2E é **lento** (segundos cada), **mais frágil** (depende de rede, navegador e dados) e, quando falha, **aponta o problema com menos precisão**. Por isso fica no **topo da pirâmide**: poucos testes, só nos **fluxos críticos** (login, checkout). Os unitários são rápidos e baratos e apontam exatamente a função com erro, por isso são muitos na base.', 'Palavras-chave: lento; frágil/instável; topo da pirâmide; fluxos críticos; unitários rápidos e precisos. Nota cheia (0,4): motivo + ideia da pirâmide com fluxos críticos. Metade (0,2): só "é lento" ou só cita a pirâmide sem explicar. Zero (0): concorda em ter só testes E2E.'),
      (v_atividade, 2, 1, 'Escreva o comando que instala cada uma das duas ferramentas.', 0.2, 'Cypress: npm install -D cypress (ou npm install --save-dev cypress). Playwright: npm init playwright@latest.', 'Palavras-chave: npm install -D cypress; npm init playwright@latest. Nota cheia (0,2): os dois comandos certos. Metade (0,1): só um comando certo, ou instala sem -D. Zero (0): nenhum comando certo.'),
      (v_atividade, 2, 2, 'Compare Cypress e Playwright em dois aspectos: navegadores suportados e estilo de escrita do código.', 0.4, '**Navegadores:** o Cypress roda em Chrome, Edge, Firefox e Electron; o Playwright roda em Chromium, Firefox e **WebKit (Safari)**. **Estilo:** o Cypress usa **comandos encadeados** (cy.get().type()); o Playwright usa **async/await** (await page.getByRole().click()). (Também vale citar: Cypress tem painel visual com "viagem no tempo"; Playwright tem várias abas e trace detalhado.)', 'Palavras-chave: WebKit/Safari no Playwright; comandos encadeados × async/await. Nota cheia (0,4): os dois aspectos corretos. Metade (0,2): só um aspecto correto. Zero (0): aspectos trocados entre as ferramentas.'),
      (v_atividade, 2, 3, 'Recomende uma das duas para esta loja e justifique a escolha pelo motivo apresentado pela equipe.', 0.4, '**Playwright**, porque ele executa os testes no **WebKit**, o motor do **Safari**, e muitos clientes compram pelo Safari do iPhone; o Cypress não roda no WebKit. A escolha é justificada pelos **navegadores exigidos** pelo público da loja.', 'Palavras-chave: Playwright; WebKit; Safari; navegadores exigidos. Nota cheia (0,4): Playwright + justificativa pelo WebKit/Safari. Metade (0,2): Playwright sem justificativa ou com justificativa genérica ("é melhor"). Zero (0): Cypress, ou sem recomendação.'),
      (v_atividade, 3, 1, 'Diga qual opção guarda o endereço base da aplicação no Cypress e no Playwright e em que arquivo cada uma fica.', 0.2, 'No Cypress, a opção **baseUrl**, no arquivo **cypress.config.js**. No Playwright, a opção **baseURL** dentro de **use**, no arquivo **playwright.config.js**.', 'Palavras-chave: baseUrl em cypress.config.js; use.baseURL em playwright.config.js. Nota cheia (0,2): as duas opções com os arquivos. Metade (0,1): só uma ferramenta, ou opções sem os arquivos. Zero (0): nenhuma opção certa.'),
      (v_atividade, 3, 2, 'Escreva a configuração do endereço base http://localhost:5173 em uma das duas ferramentas.', 0.4, 'Cypress (cypress.config.js): import { defineConfig } from ''cypress''; export default defineConfig({ e2e: { baseUrl: ''http://localhost:5173'' } }); — ou Playwright (playwright.config.js): import { defineConfig } from ''@playwright/test''; export default defineConfig({ use: { baseURL: ''http://localhost:5173'' } });', 'Palavras-chave: defineConfig; e2e.baseUrl (Cypress) ou use.baseURL (Playwright); http://localhost:5173. Nota cheia (0,4): configuração completa em uma ferramenta. Metade (0,2): opção certa fora do bloco certo (ex.: baseUrl fora de e2e) ou sem o export. Zero (0): sem a opção do endereço base.'),
      (v_atividade, 3, 3, 'Escreva os comandos que executam os testes com e sem a interface visual na ferramenta escolhida e explique por que a aplicação precisa estar rodando antes.', 0.4, 'Cypress: **npx cypress open** (com interface) e **npx cypress run** (sem interface). Playwright: **npx playwright test --ui** (com interface) e **npx playwright test** (sem interface). A aplicação precisa estar **rodando (npm run dev)** porque o teste E2E **abre o navegador e acessa o endereço real**: sem o servidor no ar, a página não carrega e todos os testes falham.', 'Palavras-chave: open/run ou test --ui/test; npm run dev; o teste acessa o endereço real. Nota cheia (0,4): os dois comandos + explicação. Metade (0,2): só os comandos ou só a explicação. Zero (0): comandos errados e sem explicação.'),
      (v_atividade, 4, 1, 'Explique por que classe de estilo não deve ser usada como seletor.', 0.2, 'A classe de estilo **muda com o layout** (troca de tema, de framework de CSS) sem mudar o comportamento; o teste **quebra à toa**, mesmo com o botão funcionando.', 'Palavras-chave: muda com o layout/visual; quebra sem defeito real. Nota cheia (0,2): motivo completo. Metade (0,1): "é ruim" sem dizer por quê. Zero (0): diz que classe é o melhor seletor.'),
      (v_atividade, 4, 2, 'Reescreva o seletor do botão Entrar de duas formas estáveis: pelo papel e nome e pelo atributo data-testid.', 0.4, 'Pelo papel e nome: cy.contains(''button'', ''Entrar'') (Cypress) ou page.getByRole(''button'', { name: ''Entrar'' }) (Playwright). Pelo atributo de teste: cy.get(''[data-testid="botao-entrar"]'') (Cypress) ou page.getByTestId(''botao-entrar'') (Playwright).', 'Palavras-chave: papel button + nome Entrar; data-testid botao-entrar. Nota cheia (0,4): as duas formas corretas (em qualquer uma das ferramentas). Metade (0,2): só uma forma correta. Zero (0): outro seletor por classe ou por estrutura (div > form > button).'),
      (v_atividade, 4, 3, 'Explique o que é escrever o teste E2E como caixa preta (3.1) e por que a ordem de preferência é papel e nome, depois rótulo, depois data-testid.', 0.4, '**Caixa preta** é testar **só pelo que o usuário vê e faz** (textos, botões, campos, resultados), **sem olhar o código interno**. Por isso a preferência começa pelo **papel e nome** e pelo **rótulo**, que são o que o usuário enxerga (e o que leitores de tela usam); o **data-testid** fica para elementos **sem texto estável**, combinado com a equipe de front-end.', 'Palavras-chave: só pelo que o usuário vê/faz; sem olhar o código; papel/rótulo = o que o usuário enxerga; data-testid para elemento sem texto estável. Nota cheia (0,4): definição + justificativa da ordem. Metade (0,2): só a definição ou só a ordem. Zero (0): confunde com caixa branca.'),
      (v_atividade, 5, 1, 'Escreva os passos do caso de teste (ação e resultado esperado), do jeito que o plano de testes descreve.', 0.2, '1) Acessar /login → formulário visível. 2) Preencher E-mail aluno@senai.br e Senha 123456. 3) Clicar em Entrar → **resultado esperado:** a URL passa a ser /dashboard e aparece a mensagem "Bem-vindo".', 'Palavras-chave: acessar /login; preencher credenciais válidas; clicar Entrar; URL /dashboard; Bem-vindo. Nota cheia (0,2): passos + resultado esperado. Metade (0,1): passos sem resultado esperado. Zero (0): sem passos.'),
      (v_atividade, 5, 2, 'Escreva em Cypress o teste completo do login aceito, com as verificações da URL e da mensagem de boas-vindas.', 0.4, 'describe(''login'', () => { it(''entra com credenciais válidas e chega ao painel'', () => { cy.visit(''/login''); cy.get(''[data-testid="campo-email"]'').type(''aluno@senai.br''); cy.get(''[data-testid="campo-senha"]'').type(''123456''); cy.get(''[data-testid="botao-entrar"]'').click(); cy.url().should(''include'', ''/dashboard''); cy.contains(''Bem-vindo'').should(''be.visible''); }); });', 'Palavras-chave: cy.visit(''/login''); type nos dois campos; click no Entrar; cy.url().should(''include'', ''/dashboard''); cy.contains(''Bem-vindo'').should(''be.visible''). Nota cheia (0,4): teste completo com as duas verificações. Metade (0,2): falta uma das verificações ou um dos campos. Zero (0): sem verificação, ou não é Cypress.'),
      (v_atividade, 5, 3, 'Escreva o mesmo teste em Playwright e explique por que nenhum dos dois precisa de espera fixa antes de verificar a mensagem.', 0.4, 'import { test, expect } from ''@playwright/test''; test(''entra com credenciais válidas'', async ({ page }) => { await page.goto(''/login''); await page.getByLabel(''E-mail'').fill(''aluno@senai.br''); await page.getByLabel(''Senha'').fill(''123456''); await page.getByRole(''button'', { name: ''Entrar'' }).click(); await expect(page).toHaveURL(/dashboard/); await expect(page.getByText(''Bem-vindo'')).toBeVisible(); }); — As duas ferramentas têm **espera automática**: elas esperam o elemento aparecer e ficar clicável e **repetem a verificação** até passar ou estourar o tempo limite, por isso não é preciso esperar um tempo fixo.', 'Palavras-chave: page.goto; getByLabel(...).fill; getByRole(''button'', { name: ''Entrar'' }).click; toHaveURL; toBeVisible; await; espera automática. Nota cheia (0,4): teste correto + explicação da espera automática. Metade (0,2): só o teste ou só a explicação, ou teste sem await. Zero (0): sem teste e sem explicação.'),
      (v_atividade, 6, 1, 'Diga quais são as duas verificações do caso de falha.', 0.2, '1) A mensagem **"Credenciais inválidas"** aparece. 2) A rota **continua /login** (o usuário não entrou).', 'Palavras-chave: mensagem Credenciais inválidas; continua em /login. Nota cheia (0,2): as duas verificações. Metade (0,1): só uma. Zero (0): nenhuma correta.'),
      (v_atividade, 6, 2, 'Escreva o teste completo do login com senha errada em Cypress ou em Playwright.', 0.4, 'Cypress: it(''continua no login e avisa quando a senha está errada'', () => { cy.visit(''/login''); cy.get(''[data-testid="campo-email"]'').type(''aluno@senai.br''); cy.get(''[data-testid="campo-senha"]'').type(''errada''); cy.get(''[data-testid="botao-entrar"]'').click(); cy.contains(''Credenciais inválidas'').should(''be.visible''); cy.url().should(''include'', ''/login''); }); — ou Playwright: test(''senha errada'', async ({ page }) => { await page.goto(''/login''); await page.getByLabel(''E-mail'').fill(''aluno@senai.br''); await page.getByLabel(''Senha'').fill(''errada''); await page.getByRole(''button'', { name: ''Entrar'' }).click(); await expect(page.getByText(''Credenciais inválidas'')).toBeVisible(); await expect(page).toHaveURL(/login/); });', 'Palavras-chave: senha diferente de 123456; verificação da mensagem; verificação da rota /login. Nota cheia (0,4): teste completo com as duas verificações. Metade (0,2): falta uma verificação. Zero (0): usa a senha certa ou não tem verificação.'),
      (v_atividade, 6, 3, 'Explique por que o teste de falha também confere a rota e não só a mensagem de erro.', 0.4, 'Porque a tela pode **mostrar a mensagem de erro e mesmo assim deixar o usuário entrar** (ou redirecionar para o painel). Conferir que a **rota continua /login** garante o que importa no caso de falha: **o acesso foi negado**. Só a mensagem não prova isso.', 'Palavras-chave: mensagem não prova que o acesso foi negado; rota /login = não entrou. Nota cheia (0,4): explicação completa. Metade (0,2): "para conferir mais coisas" sem dizer o risco. Zero (0): diz que a rota não importa.'),
      (v_atividade, 7, 1, 'Explique como cada linha da tabela do caso de teste vira parte do teste E2E (passo e verificação).', 0.2, 'Cada **etapa/ação** da tabela vira um **passo** do teste (visitar, clicar, digitar) e cada **"Verificação"** vira um **should** (Cypress) ou um **expect** (Playwright) logo depois do passo.', 'Palavras-chave: ação → passo; verificação → should/expect. Nota cheia (0,2): as duas correspondências. Metade (0,1): só uma. Zero (0): não relaciona a tabela ao teste.'),
      (v_atividade, 7, 2, 'Escreva o teste do checkout em Cypress ou Playwright com pelo menos uma verificação em cada uma das quatro etapas.', 0.4, 'Playwright: test(''finaliza a compra'', async ({ page }) => { await page.goto(''/''); await page.getByRole(''button'', { name: ''Adicionar ao carrinho'' }).first().click(); await expect(page.getByTestId(''contador-carrinho'')).toHaveText(''1''); await page.getByRole(''link'', { name: ''Carrinho'' }).click(); await page.getByLabel(''Quantidade'').fill(''2''); await expect(page.getByTestId(''subtotal'')).toHaveText(''R$ 200,00''); await page.getByRole(''link'', { name: ''Finalizar'' }).click(); await page.getByLabel(''CEP'').fill(''89160-000''); await page.getByLabel(''Cartão de teste'').fill(''4111111111111111''); await expect(page.getByRole(''button'', { name: ''Confirmar'' })).toBeEnabled(); await page.getByRole(''button'', { name: ''Confirmar'' }).click(); await expect(page.getByText(''Pedido confirmado'')).toBeVisible(); await expect(page.getByTestId(''numero-pedido'')).toBeVisible(); }); — (vale a versão em Cypress com should(''have.text'', ''1''), should(''be.enabled'') e should(''be.visible''); nomes de botões, campos e valores podem ser outros.)', 'Palavras-chave: contador = 1; quantidade 2 e subtotal; campos de entrega e pagamento + Confirmar habilitado; mensagem de sucesso e número do pedido. Nota cheia (0,4): as quatro etapas, cada uma com verificação. Metade (0,2): duas ou três etapas com verificação. Zero (0): uma etapa ou nenhuma verificação.'),
      (v_atividade, 7, 3, 'Explique por que um teste E2E sem verificação no meio do caminho é ruim para quem precisa corrigir o defeito.', 0.4, 'Sem verificação no meio, o teste **só falha no fim** e diz apenas que **"algo deu errado em algum lugar"**. Com verificação depois de cada etapa, a falha **aponta a etapa exata** (por exemplo, o subtotal errado no carrinho), e quem corrige já sabe onde procurar o defeito.', 'Palavras-chave: falha só no fim; algo deu errado em algum lugar; aponta a etapa exata. Nota cheia (0,4): explicação completa. Metade (0,2): "fica mais organizado" sem falar em localizar a falha. Zero (0): diz que não faz diferença.'),
      (v_atividade, 8, 1, 'Diga por que só o teste E2E encontrou esse defeito.', 0.2, 'Porque o defeito só aparece **no navegador real (WebKit)**, com a **tela inteira montada**: o banner de cookies **cobre o botão**. Os testes unitários e de integração rodam no Node/JSDOM, **sem desenhar a tela** nem simular a sobreposição de elementos.', 'Palavras-chave: navegador real/WebKit; tela montada de verdade; unitário/integração não desenham a tela. Nota cheia (0,2): explicação completa. Metade (0,1): "o E2E é mais completo" sem dizer por quê. Zero (0): culpa o código do botão.'),
      (v_atividade, 8, 2, 'Cite três verificações de usabilidade (4.2) que cabem num teste E2E de cadastro ou de login.', 0.4, 'Três entre: a **mensagem de erro aparece e diz o que corrigir**; depois da ação, o usuário vai para a **página certa**; os **campos têm rótulo** (getByLabel encontra); os **botões têm nome** (getByRole encontra); o fluxo funciona **só com o teclado** (Tab e Enter).', 'Palavras-chave: mensagem que diz o que corrigir; página certa depois da ação; rótulo nos campos; nome nos botões; teclado. Nota cheia (0,4): três verificações corretas. Metade (0,2): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 8, 3, 'Escreva em Playwright o trecho que preenche o login e envia o formulário só com o teclado e explique o que esse teste garante ao usuário.', 0.4, 'await page.goto(''/login''); await page.getByLabel(''E-mail'').fill(''aluno@senai.br''); await page.keyboard.press(''Tab''); await page.keyboard.type(''123456''); await page.keyboard.press(''Enter''); await expect(page).toHaveURL(/dashboard/); — O teste garante que o usuário que **não usa mouse** (por limitação motora, leitor de tela ou preferência) **consegue completar o login**: a ordem do Tab leva ao campo certo e o Enter envia o formulário.', 'Palavras-chave: keyboard.press(''Tab''); keyboard.press(''Enter''); verificação da chegada ao painel; usuário sem mouse consegue usar. Nota cheia (0,4): trecho com Tab e Enter + explicação. Metade (0,2): só o trecho ou só a explicação, ou trecho sem verificação. Zero (0): usa click no lugar do teclado.'),
      (v_atividade, 9, 1, 'Diga o que é um teste intermitente (flaky) e qual é a causa dele neste trecho.', 0.2, 'Teste **intermitente (flaky)** é o que **passa ou falha sem mudança no código**. Aqui a causa é a **espera fixa cy.wait(2000)**: na máquina lenta a lista de produtos demora mais de 2 segundos e o teste verifica antes de ela chegar.', 'Palavras-chave: passa/falha sem mudar o código; espera fixa de 2 segundos; máquina lenta. Nota cheia (0,2): definição + causa. Metade (0,1): só uma das partes. Zero (0): culpa o seletor.'),
      (v_atividade, 9, 2, 'Reescreva o trecho em Cypress esperando a requisição GET /api/produtos com cy.intercept e cy.wait(''@alias'') no lugar do tempo fixo.', 0.4, 'cy.intercept(''GET'', ''/api/produtos*'').as(''produtos''); cy.get(''[data-testid="botao-buscar"]'').click(); cy.wait(''@produtos''); cy.contains(''Teclado'').should(''be.visible'');', 'Palavras-chave: cy.intercept antes do clique; .as(''produtos''); cy.wait(''@produtos''); sem cy.wait com número. Nota cheia (0,4): trecho correto com o intercept antes da ação. Metade (0,2): intercept depois do clique, ou sem o alias. Zero (0): mantém o tempo fixo.'),
      (v_atividade, 9, 3, 'Explique por que esperar a requisição ou o elemento é mais confiável do que esperar 2 segundos, mesmo nas máquinas rápidas.', 0.4, 'A espera pela requisição ou pelo elemento **termina exatamente quando o dado chega**: na máquina lenta espera o necessário (até o tempo limite) e **não falha à toa**; na máquina rápida **não perde tempo** esperando 2 segundos inteiros. O tempo fixo é sempre um chute: **curto demais** deixa o teste instável e **longo demais** deixa a suíte lenta.', 'Palavras-chave: termina quando o dado chega; não falha na máquina lenta; não perde tempo na rápida; tempo fixo é chute. Nota cheia (0,4): os dois lados (lenta e rápida). Metade (0,2): só um lado. Zero (0): diz que basta aumentar o tempo fixo.'),
      (v_atividade, 10, 1, 'Diga qual é a causa provável de cada um dos dois problemas.', 0.2, '1) "Carrinho com 2 itens" falha depois de "adiciona produto": **dados compartilhados** — o carrinho ficou com o produto do teste anterior. 2) "Finaliza a compra" só passa depois do login: **dependência de ordem** entre testes — o teste usa o login feito por outro teste.', 'Palavras-chave: dados compartilhados; ordem/dependência entre testes. Nota cheia (0,2): as duas causas. Metade (0,1): só uma. Zero (0): nenhuma causa certa.'),
      (v_atividade, 10, 2, 'Escreva um beforeEach em Cypress ou Playwright que deixa cada teste independente (limpa o carrinho e faz o próprio login).', 0.4, 'Cypress: beforeEach(() => { cy.clearLocalStorage(); cy.clearCookies(); cy.visit(''/login''); cy.get(''[data-testid="campo-email"]'').type(''aluno@senai.br''); cy.get(''[data-testid="campo-senha"]'').type(''123456''); cy.get(''[data-testid="botao-entrar"]'').click(); cy.url().should(''include'', ''/dashboard''); }); — ou Playwright: test.beforeEach(async ({ page }) => { await page.goto(''/login''); await page.evaluate(() => localStorage.clear()); await page.getByLabel(''E-mail'').fill(''aluno@senai.br''); await page.getByLabel(''Senha'').fill(''123456''); await page.getByRole(''button'', { name: ''Entrar'' }).click(); await expect(page).toHaveURL(/dashboard/); });', 'Palavras-chave: beforeEach; limpa o carrinho/armazenamento (clearLocalStorage, localStorage.clear ou carrinho criado pelo teste); login feito no próprio beforeEach. Nota cheia (0,4): limpeza + login no beforeEach. Metade (0,2): só a limpeza ou só o login. Zero (0): sem beforeEach ou que dependa de outro teste.'),
      (v_atividade, 10, 3, 'Explique a regra de rodar a suíte 3 vezes e o que fazer com um teste que muda de resultado sem mudança no código.', 0.4, 'Rodar a suíte **3 vezes** seguidas mostra se algum teste **muda de resultado sem mudança no código**. Esse teste é **flaky** e precisa ser **corrigido** (achar a causa: espera fixa, dados compartilhados, ordem, animação) e **registrado** (teste, causa e correção) — **não ignorado** nem apagado, porque um teste em que ninguém confia deixa de proteger o sistema.', 'Palavras-chave: 3 vezes; muda de resultado sem mudar o código; corrigir a causa; não ignorar. Nota cheia (0,4): regra + o que fazer. Metade (0,2): só a regra ou só "corrigir". Zero (0): manda ignorar, rodar de novo até passar ou apagar o teste.');
end $$;
